/**
 * Cloudflare Workers entrypoint.
 *
 * - fetch: wraps the Remix Vite server build (`build/server/index.js`) with
 *   @remix-run/cloudflare's request handler, injecting the worker Env into
 *   the Remix load context as `context.cloudflare.env`.
 * - scheduled: hourly low-stock digest (PRD §6.3) — runs at 08:00 shop-local.
 */
import { createRequestHandler } from "@remix-run/cloudflare";
// @ts-ignore - generated by `remix vite:build` (build/ is gitignored, may not exist on fresh checkout)
import * as build from "./build/server/index.js";
import type { Env } from "./env";
import { runLowStockDigest } from "./app/lib/cron.server";

const handleRequest = createRequestHandler(build as any);

export default {
  async fetch(
    request: Request,
    env: Env,
    ctx: ExecutionContext
  ): Promise<Response> {
    return handleRequest(request, {
      cloudflare: { env, ctx },
    } as any);
  },

  async scheduled(
    _event: ScheduledEvent,
    env: Env,
    ctx: ExecutionContext
  ): Promise<void> {
    ctx.waitUntil(runLowStockDigest(env));
  },
};
